//! Deterministic native Rust materialization and a complete generated-role map.
//!
//! Generated byte ranges locate expected nodes in the private compiler input.
//! They are not source identity or ownership authority: the fresh compiler must
//! publish actual AST/HIR allocations, types and resolution edges for each role.
//!
//! Copyright 2026 Andrew Yates
//! SPDX-License-Identifier: Apache-2.0

use super::*;
use std::fmt::Write;

struct Emitter {
    source: String,
    roles: BTreeMap<(Site, Role), GeneratedRange>,
    auxiliary_calls: BTreeMap<(Site, Role), AuxiliaryCall>,
}
impl Emitter {
    fn text(&mut self, text: &str) {
        self.source.push_str(text);
    }
    fn mark(
        &mut self,
        site: Site,
        role: Role,
        body: impl FnOnce(&mut Self) -> Result<(), String>,
    ) -> Result<(), String> {
        let start = self.source.len();
        body(self)?;
        let end = self.source.len();
        if start == end
            || self
                .roles
                .insert((site, role), GeneratedRange { start, end })
                .is_some()
        {
            return Err("a generated native role is empty or duplicated".into());
        }
        Ok(())
    }
    fn local(&mut self, local: LocalId) {
        write!(self.source, "__local_{}", local.0).unwrap();
    }
    fn function(&mut self, function: FunctionId) {
        write!(self.source, "__function_{}", function.0).unwrap();
    }
    fn auxiliary(&mut self, kind: AuxiliaryKind) {
        self.text(match kind {
            AuxiliaryKind::ErasedValue => "__compiler_erased_value",
            AuxiliaryKind::ShadowValue => "__compiler_shadow_value",
            AuxiliaryKind::MutableTie => "__compiler_mutable_tie",
        });
    }
    fn adt_name(&mut self, adt: AdtId) {
        write!(self.source, "__Adt_{}", adt.0).unwrap();
    }
    fn field_name(&mut self, adt: AdtId, field: usize) {
        // Wrong nominal metadata cannot resolve through an equal-looking
        // field of a different generated declaration.
        write!(self.source, "__field_{}_{}", adt.0, field).unwrap();
    }
    fn type_parameters(&mut self, parameters: &[GenericId]) {
        if !parameters.is_empty() {
            self.text("<");
            for parameter in parameters {
                write!(self.source, "__Type_{},", parameter.0).unwrap();
            }
            self.text(">");
        }
    }
    fn type_arguments(&mut self, types: &[Type], turbofish: bool) -> Result<(), String> {
        if !types.is_empty() {
            self.text(if turbofish { "::<" } else { "<" });
            for ty in types {
                self.ty(ty)?;
                self.text(",");
            }
            self.text(">");
        }
        Ok(())
    }
    fn ty(&mut self, ty: &Type) -> Result<(), String> {
        match ty {
            Type::Unit => self.text("()"),
            Type::Bool => self.text("bool"),
            Type::Never => self.text("!"),
            Type::Signed(ty) => self.text(match ty {
                Signed::I8 => "i8",
                Signed::I16 => "i16",
                Signed::I32 => "i32",
                Signed::I64 => "i64",
                Signed::I128 => "i128",
                Signed::Isize => "isize",
            }),
            Type::Unsigned(ty) => self.text(match ty {
                Unsigned::U8 => "u8",
                Unsigned::U16 => "u16",
                Unsigned::U32 => "u32",
                Unsigned::U64 => "u64",
                Unsigned::U128 => "u128",
                Unsigned::Usize => "usize",
            }),
            Type::Parameter(id) => {
                write!(self.source, "__Type_{}", id.0).unwrap();
            }
            Type::Tuple(types) => {
                self.text("(");
                for ty in types {
                    self.ty(ty)?;
                    self.text(",");
                }
                self.text(")");
            }
            Type::Adt(adt, types) => {
                self.adt_name(*adt);
                self.type_arguments(types, false)?;
            }
            Type::Reference {
                region,
                mutability,
                target,
            } => {
                write!(self.source, "&'__region_{} ", region.0).unwrap();
                if *mutability == Mutability::Mutable {
                    self.text("mut ");
                }
                self.ty(target)?;
            }
        }
        Ok(())
    }
    fn binding(&mut self, binding: &Binding, with_type: bool) -> Result<(), String> {
        self.mark(binding.site, Role::Binding, |this| {
            if binding.mutable {
                this.text("mut ");
            }
            this.local(binding.id);
            Ok(())
        })?;
        if with_type {
            self.text(":");
            self.ty(&binding.ty)?;
        }
        Ok(())
    }
    fn expr(&mut self, expression: &Expr) -> Result<(), String> {
        // Locate the semantic expression inside the generated parentheses;
        // canonical HIR lowering can remove the outer AST wrapper.
        self.text("(");
        self.mark(expression.site, Role::Expression, |this| {
            match &expression.kind {
                ExprKind::Unit => this.text("()"),
                ExprKind::Bool(value) => this.text(if *value { "true" } else { "false" }),
                ExprKind::Integer { magnitude, ty } => {
                    write!(this.source, "{magnitude}u128 as ").unwrap();
                    this.ty(ty)?;
                }
                ExprKind::Unary { op, value } => {
                    this.text(match op { Unary::Not => "!", Unary::Neg => "-" });
                    this.expr(value)?;
                }
                ExprKind::Binary { op, left, right } => {
                    this.expr(left)?;
                    this.text(match op {
                        Binary::Add => "+", Binary::Sub => "-", Binary::Mul => "*", Binary::Div => "/", Binary::Rem => "%",
                        Binary::And => "&&", Binary::Or => "||", Binary::BitAnd => "&", Binary::BitOr => "|", Binary::BitXor => "^",
                        Binary::Shl => "<<", Binary::Shr => ">>", Binary::Eq => "==", Binary::Ne => "!=", Binary::Lt => "<",
                        Binary::Le => "<=", Binary::Gt => ">", Binary::Ge => ">=",
                    });
                    this.expr(right)?;
                }
                ExprKind::Cast { value, target } => { this.expr(value)?; this.text(" as "); this.ty(target)?; }
                ExprKind::TupleField { base, field } => { this.expr(base)?; write!(this.source, ".{field}").unwrap(); }
                ExprKind::StructField { base, adt, field, .. } => {
                    this.expr(base)?; this.text("."); this.field_name(*adt, *field);
                }
                ExprKind::TemporaryScope(value) => { this.text("{"); this.expr(value)?; this.text("}"); }
                ExprKind::AssignPlace { destination, value } => { this.expr(destination)?; this.text("="); this.expr(value)?; }
                ExprKind::Local(id) => this.local(*id),
                ExprKind::Tuple(values) => {
                    this.text("(");
                    for value in values {
                        this.expr(value)?;
                        this.text(",");
                    }
                    this.text(")");
                }
                ExprKind::Construct {
                    adt,
                    variant,
                    types,
                    fields,
                } => {
                    this.adt_name(*adt);
                    this.type_arguments(types, true)?;
                    write!(this.source, "::__variant_{}(", variant).unwrap();
                    for field in fields {
                        this.expr(field)?;
                        this.text(",");
                    }
                    this.text(")");
                }
                ExprKind::ConstructStruct { adt, types, fields } => {
                    this.adt_name(*adt);
                    this.type_arguments(types, true)?;
                    this.text("{");
                    for (slot, field) in fields {
                        this.field_name(*adt, *slot); this.text(":"); this.expr(field)?; this.text(",");
                    }
                    this.text("}");
                }
                ExprKind::Call {
                    function,
                    types,
                    arguments,
                } => {
                    this.function(*function);
                    this.type_arguments(types, true)?;
                    this.text("(");
                    for argument in arguments {
                        this.expr(argument)?;
                        this.text(",");
                    }
                    this.text(")");
                }
                ExprKind::Borrow { mutability, value } => {
                    this.text(if *mutability == Mutability::Mutable {
                        "&mut "
                    } else {
                        "&"
                    });
                    this.expr(value)?;
                }
                ExprKind::Dereference(value) => {
                    this.text("*");
                    this.expr(value)?;
                }
                ExprKind::Block { statements, tail } => {
                    this.text("{\n");
                    for statement in statements {
                        match statement {
                            Statement::Let {
                                binding,
                                initializer,
                            } => {
                                this.text("let ");
                                this.binding(binding, true)?;
                                if let Some(value) = initializer {
                                    this.text("=");
                                    this.expr(value)?;
                                }
                                this.text(";\n");
                            }
                            Statement::Expression(value) => {
                                this.expr(value)?;
                                this.text(";\n");
                            }
                            Statement::Shadow { binding } => {
                                if this.auxiliary_calls.insert((binding.site, Role::ShadowInitializer), AuxiliaryCall { kind: AuxiliaryKind::ShadowValue, result: Some(binding.ty.clone()) }).is_some() {
                                    return Err("a generated shadow initializer repeats an auxiliary call role".into());
                                }
                                this.text("let ");
                                this.binding(binding, true)?;
                                this.text("=");
                                this.mark(binding.site, Role::ShadowInitializer, |this| {
                                    this.auxiliary(AuxiliaryKind::ShadowValue);
                                    this.text("::<(),");
                                    this.ty(&binding.ty)?;
                                    this.text(">(())");
                                    Ok(())
                                })?;
                                this.text(";\n");
                            }
                        }
                    }
                    if let Some(value) = tail {
                        this.expr(value)?;
                    }
                    this.text("\n}");
                }
                ExprKind::If {
                    condition,
                    then_value,
                    else_value,
                } => {
                    this.text("if ");
                    this.expr(condition)?;
                    this.text("{");
                    this.expr(then_value)?;
                    this.text("} else {");
                    this.expr(else_value)?;
                    this.text("}");
                }
                ExprKind::Match { scrutinee, arms } => {
                    this.text("match ");
                    this.expr(scrutinee)?;
                    this.text("{\n");
                    for arm in arms {
                        this.mark(arm.site, Role::Arm, |this| {
                            this.pattern(&arm.pattern)?;
                            this.text("=>");
                            this.expr(&arm.body)?;
                            Ok(())
                        })?;
                        this.text(",\n");
                    }
                    this.text("}");
                }
                ExprKind::Return(value) => {
                    this.text("return");
                    if let Some(value) = value {
                        this.text(" ");
                        this.expr(value)?;
                    }
                }
                ExprKind::Assign { destination, value } => {
                    this.local(*destination);
                    this.text("=");
                    this.expr(value)?;
                }
                ExprKind::Observe { reads, result } => {
                    if this.auxiliary_calls.insert((expression.site, Role::Expression), AuxiliaryCall { kind: AuxiliaryKind::ErasedValue, result: Some(result.ty()) }).is_some() {
                        return Err("an observation repeats an auxiliary call role".into());
                    }
                    this.auxiliary(AuxiliaryKind::ErasedValue);
                    this.text("::<_,");
                    this.ty(&result.ty())?;
                    this.text(">((");
                    for read in reads {
                        this.expr(read)?;
                        this.text(",");
                    }
                    this.text("))");
                }
                ExprKind::MutableTie { first, second } => {
                    if this.auxiliary_calls.insert((expression.site, Role::Expression), AuxiliaryCall { kind: AuxiliaryKind::MutableTie, result: None }).is_some() {
                        return Err("a mutable tie repeats an auxiliary call role".into());
                    }
                    this.auxiliary(AuxiliaryKind::MutableTie);
                    this.text("(");
                    this.expr(first)?;
                    this.text(",");
                    this.expr(second)?;
                    this.text(")");
                }
            }
            Ok(())
        })?;
        self.text(")");
        Ok(())
    }
    fn pattern(&mut self, pattern: &Pattern) -> Result<(), String> {
        self.mark(pattern.site, Role::Pattern, |this| {
            match &pattern.kind {
                PatternKind::Wild => this.text("_"),
                PatternKind::Bool(value) => this.text(if *value { "true" } else { "false" }),
                PatternKind::Binding(binding) => this.binding(binding, false)?,
                PatternKind::Tuple(fields) => {
                    this.text("(");
                    for field in fields {
                        this.pattern(field)?;
                        this.text(",");
                    }
                    this.text(")");
                }
                PatternKind::Variant {
                    adt,
                    variant,
                    fields,
                } => {
                    this.adt_name(*adt);
                    write!(this.source, "::__variant_{}(", variant).unwrap();
                    for field in fields {
                        this.pattern(field)?;
                        this.text(",");
                    }
                    this.text(")");
                }
                PatternKind::Struct { adt, fields } => {
                    this.adt_name(*adt);
                    this.text("{");
                    for (slot, field) in fields {
                        this.field_name(*adt, *slot);
                        this.text(":");
                        this.pattern(field)?;
                        this.text(",");
                    }
                    this.text("}");
                }
            }
            Ok(())
        })
    }
}

pub(super) fn emit(program: &Program) -> Result<EmittedProgram, String> {
    let mut emitter = Emitter {
        source: String::new(),
        roles: BTreeMap::new(),
        auxiliary_calls: BTreeMap::new(),
    };
    emitter.text("#![feature(never_type)]\n#![allow(dead_code,unused_variables,unused_mut,unused_parens,non_camel_case_types,unreachable_code)]\n");
    if program.builtin.is_some() {
        emitter.text("extern crate builtin as __selected_builtin;\n");
    }
    for auxiliary in &program.auxiliaries {
        emitter.mark(auxiliary.site, Role::Auxiliary, |this| {
            this.text("fn ");
            this.auxiliary(auxiliary.kind);
            this.text(match auxiliary.kind {
                AuxiliaryKind::ErasedValue | AuxiliaryKind::ShadowValue =>
                    "<__Source,__Target>(__source:__Source)->__Target{loop{}}",
                AuxiliaryKind::MutableTie =>
                    "<'__tie,__First:?Sized,__Second:?Sized>(__first:&'__tie mut __First,__second:&'__tie mut __Second)->&'__tie mut __First{__first}",
            });
            Ok(())
        })?;
        emitter.text("\n");
    }
    for adt in &program.adts {
        emitter.mark(adt.site, Role::Adt, |this| {
            this.text(if adt.kind == AdtKind::Struct {
                "struct "
            } else {
                "enum "
            });
            this.adt_name(adt.id);
            this.type_parameters(&adt.generics);
            if adt.kind == AdtKind::Struct {
                let layout = &adt.variants[0];
                return this.mark(layout.site, Role::Variant, |this| {
                    this.text("{\n");
                    for (index, field) in layout.fields.iter().enumerate() {
                        this.field_name(adt.id, index);
                        this.text(":");
                        this.mark(field.site, Role::Field, |this| this.ty(&field.ty))?;
                        this.text(",\n");
                    }
                    this.text("}");
                    Ok(())
                });
            }
            this.text("{\n");
            for (index, variant) in adt.variants.iter().enumerate() {
                this.mark(variant.site, Role::Variant, |this| {
                    write!(this.source, "__variant_{}(", index).unwrap();
                    for field in &variant.fields {
                        this.mark(field.site, Role::Field, |this| this.ty(&field.ty))?;
                        this.text(",");
                    }
                    this.text(")");
                    Ok(())
                })?;
                this.text(",\n");
            }
            this.text("}");
            Ok(())
        })?;
        emitter.text("\n");
    }
    let mut roots = BTreeMap::new();
    for function in &program.functions {
        roots.insert(function.id, function.site);
        emitter.mark(function.site, Role::Function, |this| {
            this.text("fn ");
            this.function(function.id);
            if !function.regions.is_empty() || !function.generics.is_empty() {
                this.text("<");
                for region in &function.regions {
                    write!(this.source, "'__region_{},", region.0).unwrap();
                }
                for generic in &function.generics {
                    write!(this.source, "__Type_{},", generic.0).unwrap();
                }
                this.text(">");
            }
            this.text("(");
            for binding in &function.parameters {
                this.binding(binding, true)?;
                this.text(",");
            }
            this.text(")->");
            this.ty(&function.result)?;
            this.text("{\n");
            this.expr(&function.body)?;
            this.text("\n}");
            Ok(())
        })?;
        emitter.text("\n");
    }
    Ok(EmittedProgram {
        source: emitter.source,
        roles: emitter.roles,
        roots,
        builtin: program.builtin.clone(),
        auxiliary_calls: emitter.auxiliary_calls,
    })
}
